from dataclasses import dataclass
from datetime import date

@dataclass(frozen=True, slots=True)
class Effectivity:
    from_date: date
    until: date | None = None              # None = until further notice
    def __post_init__(self) -> None:
        if self.until is not None and self.until <= self.from_date:
            raise ValueError("empty period")
    def __contains__(self, as_of: date) -> bool:
        return self.from_date <= as_of and (self.until is None or as_of < self.until)
